/**
 * Order generation entry point (docs/DESIGN.md §6).
 *
 * The module touches nothing outside its input: no DOM, no storage, no randomness. Every
 * choice it makes — candidate order, tie-breaks, pruning — is a function of the input
 * alone, so the hard-constraint invariants hold on every run.
 *
 * Reproducibility is narrower than that, and it is worth being exact about. The search is
 * bounded by a wall-clock deadline. When it finishes inside that budget the solution is
 * marked `exhaustive` and is the optimum of a deterministically built candidate set, so
 * the same input always yields the same output. When the budget cuts the search short,
 * the result is the best found *so far*, and how far it got depends on the CPU the run
 * actually received: two runs of the same input on a loaded machine can stop at different
 * points and return different — equally valid, equally constraint-respecting — orders.
 *
 * `SolutionMeta.exhaustive` is what distinguishes the two cases, and the UI surfaces it
 * ("全探索完了" against "時間内の最良解") so a captain is never told an order is optimal
 * when it is merely the best one the clock allowed.
 */

export interface GenerateOptions {
  /** How many alternative candidates to return (spec §18). */
  candidateCount?: number;
  /** Overrides the per-run time budget (ms). */
  timeLimitMs?: number;
  /** Skip the alternative-preset candidates and return only the requested weights. */
  singleCandidate?: boolean;
  /**
   * Build the underdog plan when the opponent-optimised standard plan qualifies
   * (docs/UNDERDOG_PLAN.md). Default true; it is never applied, only offered.
   */
  underdog?: boolean;
}

interface RunOutcome {
  selection: Combo[];
  evaluation: Evaluation;
  meta: SolutionMeta;
  /** The bias gate chose a different line-up than the run's best by score. */
  gated: boolean;
}

function runOnce(
  ctx: PreparedContext,
  bctx: BoundContext,
  candidates: readonly GameCandidates[],
  label: string,
  presetKey: PresetKey,
  timeLimitMs: number,
  excluded: ReadonlySet<string>,
): RunOutcome | null {
  const started = performance.now();
  const found = searchOnce(ctx, bctx, candidates, timeLimitMs, excluded);
  if (!found) return null;

  let bestSelection = found.selection;
  let bestEvaluation = found.evaluation;
  const stage = found.stage;

  // Opponent-aware runs: the search ranks by the additive score (expected games won plus
  // the soft terms); the final pick among the near-optimal line-ups is the one with the
  // best estimated *match* outcome, which is not additive in the games.
  const pool = [...found.pool, ...(found.dfsBest ? [found.dfsBest] : [])];
  if ((ctx.weights.opponentWin ?? 0) > 0 && ctx.opponent) {
    const reranked = rerankByMatchOutcome(ctx, [...pool, bestSelection], bestEvaluation);
    if (reranked) {
      bestSelection = reranked.selection;
      bestEvaluation = reranked.evaluation;
    }
  }

  // Bias towards stronger players has to earn its place over the even split.
  const gate = applySkewGate({
    ctx,
    presetKey,
    best: { selection: bestSelection, evaluation: bestEvaluation },
    pool: [...pool, bestSelection],
    excluded,
    timeLimitMs,
  });

  return {
    selection: gate.selection,
    evaluation: gate.evaluation,
    gated: gate.changed,
    meta: {
      stage,
      exhaustive: found.exhaustive && gate.exhaustive,
      nodesVisited: found.nodes,
      elapsedMs: round(performance.now() - started, 1),
      label,
      presetKey,
      ...(gate.report ? { skewGate: gate.report } : {}),
    },
  };
}

/**
 * Turns a selection into slot-ordered assignments: each game's members in their throwing order
 * (`Combo.order`, which keeps every locked player in their locked slot — docs/THROW_ORDER_MODEL.md
 * §6). Never the internal id order.
 */
export function materialise(ctx: PreparedContext, selection: readonly Combo[]): GameAssignment[] {
  return selection.map((combo, gi) => ({
    gameId: ctx.games[gi].id,
    playerIds: combo.order.map((pi) => ctx.playerIds[pi]),
  }));
}

/**
 * How each multi-player game's order was decided, for the solution. Orders made before the
 * throw-order model (no model version in their input) get none: they keep the order they were
 * saved in and are explained as before, never as hand edits of a rule they did not follow.
 */
export function throwOrderRecords(ctx: PreparedContext, selection: readonly Combo[]): ThrowOrderRecord[] {
  if (!ctx.throwOrderModel) return [];
  return selection.flatMap((combo, gi) => (combo.members.length >= 2 ? [throwOrderRecord(ctx, gi, combo.orderChoice)] : []));
}

/** One reason per multi-player game: which order, and why (docs/THROW_ORDER_MODEL.md §7). */
function withThrowOrderFactors(ctx: PreparedContext, explanation: OrderExplanation, records: readonly ThrowOrderRecord[]): OrderExplanation {
  if (records.length === 0) return explanation;
  const nameOf = (id: string): string => ctx.players[ctx.playerIndex.get(id) ?? -1]?.name ?? id;
  const byGame = new Map(records.map((record) => [record.gameId, record]));
  return {
    ...explanation,
    games: explanation.games.map((game) => {
      const record = byGame.get(game.gameId);
      if (!record) return game;
      const text = describeThrowOrder(record, nameOf);
      const factor: ExplanationFactor = {
        key: 'throwOrder',
        label: text.summary,
        detail: text.detail,
        tone: text.deviates ? 'neutral' : 'positive',
      };
      return { ...game, factors: [factor, ...game.factors] };
    }),
  };
}

function buildTallies(ctx: PreparedContext, evaluation: Evaluation): PlayerTally[] {
  return ctx.playerIds.map((playerId, pi) => {
    const player = ctx.players[pi];
    const countByKind: PlayerTally['countByKind'] = {};
    for (const gameIndex of evaluation.appearances[pi]) {
      for (const kind of ctx.games[gameIndex].kinds) {
        countByKind[kind] = (countByKind[kind] ?? 0) + 1;
      }
    }
    const indices = evaluation.appearances[pi];
    let maxRun = 0;
    let run = 0;
    for (let i = 0; i < indices.length; i += 1) {
      run = i > 0 && indices[i] === indices[i - 1] + 1 ? run + 1 : 1;
      if (run > maxRun) maxRun = run;
    }
    return {
      playerId,
      count: evaluation.counts[pi],
      seasonBefore: player.seasonAppearances,
      seasonTotal: player.seasonAppearances + evaluation.counts[pi],
      // Like PPR below: an imputed Rating is only reported when Rating took part in
      // scoring, otherwise the screen would claim a median was used that never was.
      effectiveRating:
        ctx.strengthWeights.rating > 0 || !ctx.ratings.imputed.has(playerId)
          ? (ctx.ratings.effective.get(playerId) ?? null)
          : null,
      ratingImputed: ctx.strengthWeights.rating > 0 && ctx.ratings.imputed.has(playerId),
      // An imputed PPR is only reported when PPR actually took part in scoring; otherwise
      // the median would be shown next to players who never entered one.
      effectivePpr:
        ctx.strengthWeights.ppr > 0 || !ctx.pprs.imputed.has(playerId)
          ? (ctx.pprs.effective.get(playerId) ?? null)
          : null,
      pprImputed: ctx.strengthWeights.ppr > 0 && ctx.pprs.imputed.has(playerId),
      maxConsecutive: maxRun,
      countByKind,
    };
  });
}

function buildMetrics(ctx: PreparedContext, evaluation: Evaluation): OrderMetrics {
  return {
    totalSlots: ctx.totalSlots,
    participantCount: ctx.playerCount,
    appearanceSpread: evaluation.fairness.spread,
    appearanceStdDev: round(evaluation.fairness.stdDev),
    fairnessExcess: round(evaluation.fairness.excess, 4),
    maxConsecutive: evaluation.maxConsecutive,
    averageRating: evaluation.averageRating === null ? null : round(evaluation.averageRating, 2),
    averagePpr: evaluation.averagePpr === null ? null : round(evaluation.averagePpr, 2),
    hasImputedRating: ctx.strengthWeights.rating > 0 && ctx.ratings.imputed.size > 0,
    strengthWeights: { ...ctx.strengthWeights },
    discipline: ctx.discipline,
    maxRoleConcentration: evaluation.roleFairness.maxConcentration,
  };
}

function buildWarnings(
  ctx: PreparedContext,
  evaluation: Evaluation,
  candidates: readonly GameCandidates[],
  meta: SolutionMeta,
): OrderWarning[] {
  const warnings: OrderWarning[] = [];

  if (evaluation.fairness.spread > 1) {
    warnings.push({
      severity: 'warning',
      code: 'SPREAD_OVER_ONE',
      message: `出場回数の最大差が ${evaluation.fairness.spread} です。絶対条件 (出場不可・最大出場回数・ロック)、または方針の重み付けにより完全な均等化はしていません。`,
    });
  }
  if (evaluation.consecutiveExcessTotal > 0) {
    warnings.push({
      severity: 'warning',
      code: 'CONSECUTIVE_OVER',
      message: `最大連続出場の上限超過が ${evaluation.consecutiveExcessTotal} 箇所あります (設定が「できるだけ考慮」のため配置は有効です)。`,
    });
  }
  const { rating: ratingShare, ppr: pprShare } = ctx.strengthWeights;
  if (ratingShare + pprShare <= 0) {
    warnings.push({
      severity: 'info',
      code: 'NO_RATING',
      message:
        ctx.ratings.knownCount === 0 && ctx.pprs.knownCount === 0
          ? 'Rating・PPR が 1 名も入力されていないため、戦力評価は使用していません (適性と公平性で生成しました)。'
          : 'Rating・PPR が参加者全員で同じ値のため、戦力に差が付かず戦力評価は使用していません (適性と公平性で生成しました)。',
    });
  } else {
    if (ratingShare > 0 && ctx.ratings.imputed.size > 0) {
      warnings.push({
        severity: 'info',
        code: 'RATING_IMPUTED',
        message: `Rating 未入力 ${ctx.ratings.imputed.size} 名は 0 ではなく参加者の中央値で評価しています。`,
      });
    }
    if (pprShare > 0 && ctx.pprs.imputed.size > 0) {
      warnings.push({
        severity: 'info',
        code: 'PPR_IMPUTED',
        message: `PPR 未入力 ${ctx.pprs.imputed.size} 名は 0 ではなく参加者の中央値で評価しています。`,
      });
    }
  }
  for (let pi = 0; pi < ctx.playerCount; pi += 1) {
    if (
      ctx.input.settings.minAppearanceMode === 'soft' &&
      evaluation.counts[pi] < ctx.minAppearances[pi]
    ) {
      warnings.push({
        severity: 'warning',
        code: 'MIN_UNMET_SOFT',
        playerId: ctx.playerIds[pi],
        message: `${ctx.players[pi].name}: 最小出場回数 ${ctx.minAppearances[pi]} に届いていません (${evaluation.counts[pi]} 回)。`,
      });
    }
  }
  const plan = ctx.opponentPlan;
  if (plan?.mode === 'fallback') {
    warnings.push({
      severity: 'warning',
      code: 'OPPONENT_DATA_MISSING',
      message: '対戦データ不足のため、対戦相手の予測を使わず通常の勝利優先 (戦力重視) で生成しました。',
    });
  } else if (plan?.mode === 'reduced' && plan.confidence) {
    warnings.push({
      severity: 'info',
      code: 'OPPONENT_WEIGHT_REDUCED',
      message: `対戦相手データの信頼度が「${CONFIDENCE_LABELS[plan.confidence]}」のため、対戦相手の影響を ${Math.round(
        CONFIDENCE_WEIGHT_FACTOR[plan.confidence] * 100,
      )}% に弱め、通常の戦力評価に寄せています。`,
    });
  }
  if (meta.skewGate?.outcome === 'unverified') {
    warnings.push({
      severity: 'warning',
      code: 'SKEW_UNVERIFIED',
      message: '均等案を探索できなかったため、この案の出場の偏りが妥当かは検証できていません。',
    });
  }
  if (!meta.exhaustive && meta.skewGate?.outcome !== 'unverified') {
    const capped = candidates.filter((entry) => !entry.complete).length;
    warnings.push({
      severity: 'info',
      code: 'NOT_EXHAUSTIVE',
      message:
        capped > 0
          ? `探索空間が大きいため ${capped} ゲームで候補を間引きました。最良解である保証はありません (時間上限 ${ctx.input.settings.timeLimitMs}ms)。`
          : `時間上限に達したため全探索は完了していません。表示中の案は時間内の最良解です。`,
    });
  }
  return warnings;
}

function roundScore(breakdown: ScoreBreakdown): ScoreBreakdown {
  return {
    strength: round(breakdown.strength),
    gameFit: round(breakdown.gameFit),
    pairFit: round(breakdown.pairFit),
    fairness: round(breakdown.fairness),
    roleFairness: breakdown.roleFairness === undefined ? undefined : round(breakdown.roleFairness),
    novelty: round(breakdown.novelty),
    consecutivePenalty: round(breakdown.consecutivePenalty),
    seasonImbalance: round(breakdown.seasonImbalance),
    ...(breakdown.opponentWin === undefined ? {} : { opponentWin: round(breakdown.opponentWin) }),
    total: round(breakdown.total, 4),
    display: round(breakdown.display, 1),
  };
}

function assembleSolution(
  ctx: PreparedContext,
  bctx: BoundContext,
  candidates: readonly GameCandidates[],
  outcome: RunOutcome,
  /**
   * Scoring context for the weights the *captain* chose. Each candidate is generated
   * under its own preset's weights, so reporting each one's score under those weights
   * would make the comparison screen meaningless (a fairness-first line-up would always
   * look best on its own scale). The reported total is therefore always measured against
   * the captain's weights; the individual components are weight-independent.
   */
  referenceCtx: PreparedContext,
): OrderSolution | null {
  const assignments = materialise(ctx, outcome.selection);
  const violations = validateHardConstraints(ctx.input, assignments);
  if (violations.length > 0) return null;

  // Reported on the captain's scale: an underdog run's opponent term is a transform of the win
  // probabilities, so its line-up is re-described under the reference context first.
  const comparable = evaluateSelection(
    referenceCtx,
    ctx.objective === referenceCtx.objective
      ? outcome.selection
      : outcome.selection.map((combo, gi) => describeCombo(referenceCtx, gi, combo.members, combo.order)),
  );
  const prediction = ctx.opponent
    ? (predictOrder(ctx.opponent, assignments, ctx.input.pairs, independentGamesModel, ctx.predictionOptions) ?? undefined)
    : undefined;

  const throwOrder = throwOrderRecords(ctx, outcome.selection);
  return {
    assignments,
    tallies: buildTallies(ctx, outcome.evaluation),
    score: roundScore(comparable.breakdown),
    metrics: buildMetrics(ctx, outcome.evaluation),
    explanation: withThrowOrderFactors(
      ctx,
      withPredictionFactors(
        withSkewFactor(ctx, buildExplanation(ctx, bctx, outcome.selection, outcome.evaluation), outcome.meta.skewGate),
        prediction,
      ),
      throwOrder,
    ),
    warnings: buildWarnings(ctx, outcome.evaluation, candidates, outcome.meta),
    meta: ctx.opponentPlan ? { ...outcome.meta, opponent: ctx.opponentPlan } : outcome.meta,
    prediction,
    throwOrder,
  };
}

const countsText = (ctx: PreparedContext, counts: Record<string, number>): string =>
  ctx.playerIds.map((id, index) => `${ctx.players[index].name} ${counts[id] ?? 0}`).join(' / ');

const points = (value: number): string => `${(value * 100).toFixed(1)}pt`;

/**
 * The bias gate's verdict as a reason (docs/DESIGN.md, appearance bias): which split was
 * judged against the even one, the gain measured, what it had to reach and on what data.
 * Worded as an estimate; with no opponent the measure is a model reference, not a win rate.
 */
function withSkewFactor(ctx: PreparedContext, explanation: OrderExplanation, report: SkewGateReport | undefined): OrderExplanation {
  if (!report) return explanation;
  const even = countsText(ctx, report.evenCounts);
  const biased = countsText(ctx, report.biasedCounts);
  const measure =
    report.basis === 'opponent'
      ? '推定 Match 勝率の差'
      : '同等戦力の相手を仮定した期待値の差 (勝率ではなく参考値)';
  const needed = report.required === null ? '—' : points(report.required);
  const factor: ExplanationFactor =
    report.outcome === 'unverified'
      ? {
          key: 'fairness',
          label: '出場の偏りは未検証',
          detail: `この案 (${biased}) は均等配分から偏っていますが、比べる均等案を (既出の案と重ならない形で) 探索できなかったため、偏りが妥当か検証できていません。探索は未完了です。`,
          tone: 'negative',
        }
      : report.outcome === 'kept'
      ? {
          key: 'fairness',
          label: '出場の偏りを採用',
          detail: `均等案 (${even}) ではなく ${biased} を採用: ${measure} ${points(report.gain)} が必要な ${needed} を上回り、データの信頼度は「${CONFIDENCE_LABELS[report.confidence]}」です。`,
          tone: 'neutral',
        }
      : {
          key: 'fairness',
          label: '出場の偏りは見送り (均等配分)',
          detail:
            report.required === null
              ? `戦力差を活かす案 (${biased}) は、データの信頼度が「${CONFIDENCE_LABELS[report.confidence]}」で偏りの根拠にできないため見送り、均等案 (${even}) にしました。`
              : `戦力差を活かす案 (${biased}) は、${measure} ${points(report.gain)} が必要な ${needed} に届かないため見送り、均等案 (${even}) にしました。`,
          tone: 'neutral',
        };
  return { ...explanation, overall: [factor, ...explanation.overall] };
}

/**
 * Adds the estimated win probabilities to the reasons (MASTER SPEC Phase 3 §12): one
 * factor per game with its confidence and why, and the match estimate at the top of the
 * summary. Worded as estimates; LOW confidence is called 参考値.
 */
function withPredictionFactors(
  explanation: OrderExplanation,
  prediction: OrderSolution['prediction'],
): OrderExplanation {
  if (!prediction) return explanation;
  const byGame = new Map(prediction.games.map((game) => [game.gameId, game]));
  const tone = (p: number): ExplanationFactor['tone'] => (p >= 0.55 ? 'positive' : p <= 0.45 ? 'negative' : 'neutral');
  return {
    games: explanation.games.map((game) => {
      const predicted = byGame.get(game.gameId);
      if (!predicted) return game;
      return {
        ...game,
        factors: [
          {
            key: 'opponent',
            label: '推定ゲーム勝率',
            value: predicted.probability,
            detail: `${formatProbability(predicted.probability)} (${confidenceText(predicted.confidence)}) ・ ${predicted.reasons.join(' ・ ')}`,
            tone: tone(predicted.probability),
          },
          ...game.factors,
        ],
      };
    }),
    overall: [
      {
        key: 'opponent',
        label: `推定 Match 勝率 (vs ${prediction.opponentName})`,
        value: prediction.win,
        detail: `${formatProbability(prediction.win)} ・ 期待勝ちゲーム ${prediction.expectedGames.toFixed(1)} / ${prediction.gameCount} ・ ${confidenceText(prediction.confidence)}。${INDEPENDENCE_NOTE}`,
        tone: tone(prediction.win),
      },
      ...explanation.overall,
    ],
  };
}

/**
 * When an already-shown line-up scores at least as well under this run's weights as the
 * run's own result, the preset's optimum *is* a shown line-up: the run only produced a
 * different order because shown line-ups are excluded. The optimum is the
 * highest-scoring of those line-ups (the earliest on a tie), so every shown line-up is
 * scored before one is named. Exported for tests.
 */
export function bestShownLineUp(
  ctx: PreparedContext,
  shown: readonly { label: string; members: PlayerId[][] }[],
  achieved: number,
): string | undefined {
  const EPSILON = 1e-9;
  let best: { label: string; total: number } | undefined;
  for (const entry of shown) {
    const selection: Combo[] = [];
    let valid = entry.members.length === ctx.gameCount;
    for (let gi = 0; valid && gi < ctx.gameCount; gi += 1) {
      const members = entry.members[gi].map((id) => ctx.playerIndex.get(id));
      if (members.some((pi) => pi === undefined)) {
        valid = false;
        break;
      }
      selection.push(describeCombo(ctx, gi, (members as number[]).sort((a, b) => a - b)));
    }
    if (!valid) continue;
    const total = evaluateSelection(ctx, selection).breakdown.total;
    if (total < achieved - EPSILON) continue;
    if (!best || total > best.total + EPSILON) best = { label: entry.label, total };
  }
  return best?.label;
}

function signature(assignments: readonly GameAssignment[]): string {
  return assignments.map((a) => `${a.gameId}:${a.playerIds.join('-')}`).join('|');
}

/**
 * Generates up to `candidateCount` line-ups: the first uses the requested weights, the
 * rest use the comparison presets (win-first / balanced / fairness-first) so the captain
 * can weigh the trade-offs side by side.
 */
export function generateOrder(input: OrderInput, options: GenerateOptions = {}): GenerateResult {
  // Static conflicts are reported before any search: a contradiction in the input is a
  // configuration problem to explain, not something to search around.
  const diagnostics = precheck(input);
  if (diagnostics.length > 0) {
    return { ok: false, candidates: [], diagnostics };
  }

  const generationStarted = performance.now();
  const timeLimit = options.timeLimitMs ?? input.settings.timeLimitMs;
  const runs: { label: string; presetKey: PresetKey; weights: ScoreWeights }[] = [
    {
      label: input.preset === 'CUSTOM' ? 'カスタム' : PRESETS[input.preset].label,
      presetKey: input.preset,
      weights: input.weights,
    },
  ];

  if (!options.singleCandidate) {
    const opponentRun = input.preset === 'OPPONENT_OPTIMIZED';
    const wanted = Math.max(1, options.candidateCount ?? (opponentRun ? OPPONENT_CANDIDATE_PRESETS.length : 3));
    for (const presetKey of opponentRun ? OPPONENT_CANDIDATE_PRESETS : CANDIDATE_PRESETS) {
      if (runs.length >= wanted) break;
      if (presetKey === input.preset) continue;
      runs.push({
        label: PRESETS[presetKey].label,
        presetKey,
        weights: PRESETS[presetKey].weights,
      });
    }
  }

  // The captain's own weights define the scale every candidate is reported on.
  const referenceCtx = prepare(input);
  const perRunBudget = Math.max(120, Math.floor(timeLimit / runs.length));
  const solutions: OrderSolution[] = [];
  const seen = new Set<string>();
  const excluded = new Set<string>();
  /** Earlier candidates as player-id line-ups, to recognise a preset that agrees with one. */
  const shown: { label: string; members: PlayerId[][] }[] = [];

  for (const run of runs) {
    const runInput: OrderInput = { ...input, weights: run.weights };
    const ctx = prepare(runInput);
    const candidates = buildAllCandidates(ctx);
    if (candidates.some((entry) => entry.combos.length === 0)) continue;
    const bctx = buildBoundContext(ctx, candidates);
    const outcome = runOnce(
      ctx,
      bctx,
      candidates,
      run.label,
      run.presetKey,
      perRunBudget,
      excluded,
    );
    if (!outcome) continue;
    // "Same optimum" is only claimed when the run proved its result optimal; a run cut
    // short by the clock or by capped candidate sets may have missed a better order.
    // A line-up the bias gate chose over the run's best by score is not that run's optimum,
    // so it never claims to be a shown one's twin.
    const sameAs =
      outcome.meta.exhaustive && !outcome.gated
        ? bestShownLineUp(ctx, shown, outcome.evaluation.breakdown.total)
        : undefined;
    if (sameAs) outcome.meta = { ...outcome.meta, alternativeTo: sameAs };
    const solution = assembleSolution(ctx, bctx, candidates, outcome, referenceCtx);
    if (!solution) continue;
    const key = signature(solution.assignments);
    if (seen.has(key)) continue;
    seen.add(key);
    excluded.add(selectionSignature(ctx, outcome.selection));
    shown.push({
      label: run.label,
      members: outcome.selection.map((combo) => combo.members.map((pi) => ctx.playerIds[pi])),
    });
    solutions.push(solution);
  }

  if (solutions.length === 0) {
    const suggestions = analyseRelaxations(input);
    const rules = describeLeagueRules(input.leagueRules);
    return {
      ok: false,
      candidates: [],
      diagnostics: [
        {
          code: 'SEARCH_EXHAUSTED',
          message:
            'すべての絶対条件を満たすオーダーが見つかりませんでした。制約を自動的に破ることはしません。' +
            (rules.length > 0
              ? ` リーグ規則 (必須条件: ${rules.join(' ・ ')}) も緩めずに探索しています。下の解決候補はリーグ規則を守ったまま成立を確認したものです。`
              : ''),
          suggestions:
            suggestions.length > 0
              ? suggestions
              : [
                  {
                    kind: 'other',
                    message:
                      '単一の制約緩和では解決できませんでした。参加者の追加、出場不可設定の見直し、最大出場回数の引き上げを組み合わせて調整してください。',
                  },
                ],
        },
      ],
    };
  }

  if (input.preset === 'OPPONENT_OPTIMIZED' && options.underdog !== false) {
    const standard = solutions.find((solution) => solution.meta.presetKey === 'OPPONENT_OPTIMIZED' && !solution.meta.underdog);
    // The two underdog runs share what is left of the time limit (each at least the per-run
    // floor), so the whole generation stays within the limit the captain set.
    const remaining = timeLimit - (performance.now() - generationStarted);
    const underdogBudget = Math.max(UNDERDOG_MIN_RUN_MS, Math.floor(remaining / 2));
    const { suggestion, status } = planUnderdog(input, standard, referenceCtx, underdogBudget);
    return { ok: true, candidates: solutions, diagnostics: [], underdogStatus: status, ...(suggestion ? { underdog: suggestion } : {}) };
  }
  return { ok: true, candidates: solutions, diagnostics: [] };
}

/**
 * The underdog plan (docs/UNDERDOG_PLAN.md): when the standard plan qualifies, the same engine is
 * run twice more — on the same weights, hard conditions and fairness terms — maximising
 * P(W ≥ 1) and E[W] instead of the match value, and the better of the two on the common scale is
 * offered. The standard plan is never touched.
 */
function planUnderdog(
  input: OrderInput,
  standard: OrderSolution | undefined,
  referenceCtx: PreparedContext,
  budget: number,
): { suggestion: UnderdogSuggestion | null; status: UnderdogStatus } {
  const status = underdogEligibility(standard?.prediction, referenceCtx.opponent);
  if (!status.eligible || !standard?.prediction || !referenceCtx.opponent) return { suggestion: null, status };
  const standardMetrics = planMetrics(standard.prediction);
  const plans: Partial<Record<UnderdogObjective, UnderdogPlanMetrics>> = {};
  const solutionsByObjective: Partial<Record<UnderdogObjective, OrderSolution>> = {};
  for (const objective of ['atLeastOne', 'expectedWins'] as const) {
    const ctx = prepare({ ...input, searchObjective: objective });
    const candidates = buildAllCandidates(ctx);
    if (candidates.some((entry) => entry.combos.length === 0)) continue;
    const bctx = buildBoundContext(ctx, candidates);
    const outcome = runOnce(ctx, bctx, candidates, UNDERDOG_LABEL, 'OPPONENT_OPTIMIZED', budget, new Set());
    if (!outcome) continue;
    outcome.meta = { ...outcome.meta, underdog: { objective } };
    const solution = assembleSolution(ctx, bctx, candidates, outcome, referenceCtx);
    if (!solution?.prediction) continue;
    plans[objective] = planMetrics(solution.prediction);
    solutionsByObjective[objective] = solution;
  }
  // Neither run produced a plan (no feasible line-up): nothing was compared, so nothing "did not improve".
  if (Object.keys(plans).length === 0) return { suggestion: null, status: { eligible: false, reason: 'not-run' } };
  const choice = chooseUnderdogPlan(standardMetrics, plans);
  if (!choice) return { suggestion: null, status: { eligible: false, reason: 'no-improvement' } };
  const chosen = solutionsByObjective[choice.objective]!;
  const plan = plans[choice.objective]!;
  const solution: OrderSolution = {
    ...chosen,
    explanation: {
      ...chosen.explanation,
      overall: [
        {
          key: 'opponent',
          label: UNDERDOG_LABEL,
          detail: describeUnderdogChoice(choice.objective, standardMetrics, plan),
          tone: 'neutral',
        },
        ...chosen.explanation.overall,
      ],
    },
  };
  return {
    status,
    suggestion: {
      version: 1,
      objective: choice.objective,
      solution,
      standard: standardMetrics,
      plan,
      improvement: choice.improvement,
      compared: choice.compared,
      matchWinLoss: standardMetrics.win - plan.win,
      confidence: opponentDataConfidence(referenceCtx.opponent),
    },
  };
}

export const UNDERDOG_LABEL = '格上対策案';
/** The smallest search budget an underdog run gets, even when the standard runs used the whole limit. */
export const UNDERDOG_MIN_RUN_MS = 120;

/** Why the underdog plan is what it is, in estimates (docs/UNDERDOG_PLAN.md §5). */
export function describeUnderdogChoice(objective: UnderdogObjective, standard: UnderdogPlanMetrics, plan: UnderdogPlanMetrics): string {
  return `標準案 (推定 Match 勝率 ${formatProbability(standard.win)}) に対し、${underdogGainText(objective, standard, plan)}。${underdogLossText(standard, plan)}。推定値であり、結果を保証するものではありません。`;
}

/**
 * Re-optimises while keeping the given locks fixed (spec §17).
 *
 * This is the same entry point as `generateOrder` — the locks are what make it
 * "partial". Pass the locks derived from the games the captain wants to keep (e.g. the
 * one they just edited by hand, or every game except the one that must change).
 */
export function reoptimise(input: OrderInput, options: GenerateOptions = {}): GenerateResult {
  return generateOrder(input, { ...options, candidateCount: options.candidateCount ?? 1 });
}

/**
 * Evaluates an assignment the captain produced by hand (spec §15).
 *
 * Metrics, tallies and reasons are always returned — even when a hard constraint is
 * violated — because the result screen has to show the captain *what* broke and by how
 * much, live, while they are still editing. `ok` reports whether the assignment is
 * legal; `violations` lists every breach.
 */
export interface ManualEvaluation {
  ok: boolean;
  solution: OrderSolution | null;
  violations: HardViolation[];
}

export function evaluateManualOrder(
  input: OrderInput,
  assignments: readonly GameAssignment[],
): ManualEvaluation {
  const violations = validateHardConstraints(input, assignments);
  const ctx = prepare(input);
  const candidates = buildAllCandidates(ctx);
  const bctx = buildBoundContext(ctx, candidates);

  const byGame = new Map(assignments.map((a) => [a.gameId, a]));
  const selection: Combo[] = [];
  for (let gi = 0; gi < ctx.gameCount; gi += 1) {
    const assignment = byGame.get(ctx.games[gi].id);
    if (!assignment) return { ok: false, solution: null, violations };
    // The captain's slots are the throwing order: kept exactly as edited, and estimated as such.
    const order = assignment.playerIds
      .map((id) => ctx.playerIndex.get(id))
      .filter((index): index is number => index !== undefined);
    // An unknown or duplicated player cannot be scored; the violation list already says so.
    if (order.length !== assignment.playerIds.length || new Set(order).size !== order.length) {
      return { ok: false, solution: null, violations };
    }
    const members = [...order].sort((a, b) => a - b);
    selection.push(describeCombo(ctx, gi, members, order));
  }

  const evaluation = evaluateSelection(ctx, selection);
  const meta: SolutionMeta = {
    stage: 'dfs',
    exhaustive: false,
    nodesVisited: 0,
    elapsedMs: 0,
    label: '手動編集',
    presetKey: input.preset,
    ...(ctx.opponentPlan ? { opponent: ctx.opponentPlan } : {}),
  };
  const copied = assignments.map((a) => ({ ...a, playerIds: [...a.playerIds] }));
  const throwOrder = throwOrderRecords(ctx, selection);
  // A hand edit is re-estimated live, exactly like every other number on the screen — with the
  // model the order was generated with (an order saved before the throw-order model keeps its own).
  const prediction = ctx.opponent
    ? (predictOrder(ctx.opponent, copied, input.pairs, independentGamesModel, ctx.predictionOptions) ?? undefined)
    : undefined;
  const solution: OrderSolution = {
    assignments: copied,
    tallies: buildTallies(ctx, evaluation),
    score: roundScore(evaluation.breakdown),
    metrics: buildMetrics(ctx, evaluation),
    // The reasons are told about the violations, so a hand-edited line-up never gets a
    // "nothing is violated" rationale while the validator says otherwise (spec §15).
    explanation: withThrowOrderFactors(ctx, withPredictionFactors(buildExplanation(ctx, bctx, selection, evaluation, violations), prediction), throwOrder),
    warnings: buildWarnings(ctx, evaluation, candidates, meta),
    meta,
    prediction,
    throwOrder,
  };
  return { ok: violations.length === 0, solution, violations };
}
